#include <stdlib.h>
#include <stdio.h>
#include <sys/stat.h>
#include <limits.h>

// Assuming a global flag `umask_set_from_cmdline` exists based on the context
extern int umask_set_from_cmdline;

mode_t set_umask_from_string(const char *optarg) {
    char *endptr;
    long umask_value;
    mode_t new_umask;

    // Convert optarg to long integer
    umask_value = strtol(optarg, &endptr, 10);

    // Check for conversion errors and out-of-range values
    if (optarg == endptr || *endptr != '\0' || umask_value < 0 || umask_value > USHRT_MAX) {
        fprintf(stderr, "Invalid umask value: %s\n", optarg);
        return 0;
    }

    // Apply the umask
    new_umask = (mode_t)umask_value;
    umask(new_umask);

    // Set the global flag to indicate umask was set from command line
    umask_set_from_cmdline = 1;

    return new_umask;
}

